import {ALL_PRODUCTS,PRODUCT_ALIASES,productPrice,productAllowed} from './core.js?v=20261014-450';
import {artKind} from './product-art.js?v=20261014-450';
export const SHOP_CATEGORIES=[['all','Все продукты','grid'],['vegetables','Овощи и зелень','leaf'],['fruits','Фрукты и ягоды','sun'],['dairy','Молоко и яйца','bag'],['cheese','Сыры','bag'],['meat','Мясо и птица','fork'],['fish','Рыба','fork'],['bread','Хлеб и выпечка','sun'],['grocery','Бакалея','bag'],['frozen','Заморозка','spark'],['ready','Готовая еда','fork'],['drinks','Напитки','bag'],['tea','Чай и кофе','sun'],['sweets','Сладости','heart'],['snacks','Орехи и снеки','bag'],['sauces','Соусы и консервы','bag']];
export function productCategory(p){const a=p.aisle.toLowerCase(),k=artKind(p),n=p.name.toLowerCase();if(/готов|кулинари/.test(a)||k==='meal')return 'ready';if(/замороз|морожен/.test(a)||k==='frozen')return 'frozen';if(k==='cheese'||/сыры/.test(a))return 'cheese';if(['milk','yogurt','egg'].includes(k)||/молоч/.test(a))return 'dairy';if(['meat','chicken'].includes(k)||/мяс|птиц|колбас/.test(a))return 'meat';if(k==='fish'||/рыба|морепродукт/.test(a))return 'fish';if(/фрукт|ягод/.test(a)||['apple','banana','citrus','berries','grapes'].includes(k))return 'fruits';if(/овощ|зелень/.test(a)||['avocado','tomato','cucumber','carrot','potato','greens','pepper','mushroom'].includes(k))return 'vegetables';if(['bread','pastry'].includes(k)||/хлеб|выпечк/.test(a))return 'bread';if(['tea','coffee'].includes(k)||/чай|кофе/.test(a))return 'tea';if(k==='juice'||/напит|воды|соки/.test(a)||/вода питьевая/.test(n))return 'drinks';if(/слад|кондитер/.test(a)||['chocolate','cookie'].includes(k))return 'sweets';if(/орех|сухофрукт|снек|чипс/.test(a)||k==='nuts')return 'snacks';if(/соус|консерв|масла|спец/.test(a)||['jar','bottle'].includes(k))return 'sauces';return 'grocery';}
const featured=['tomato','cucumber','apple','banana','milk','egg','bread','chicken','cheese','rice','avocado','salmon','yogurt','potato','orange','pasta','butter','oats'];
export const SHOP_ITEMS=Object.entries(ALL_PRODUCTS).filter(([id])=>!PRODUCT_ALIASES[id]).map(([id,p])=>({id,...p,category:productCategory(p)})).sort((a,b)=>{const ai=featured.indexOf(a.id),bi=featured.indexOf(b.id);return (ai<0?999:ai)-(bi<0?999:bi);});
export function shopFilter(s,options={}){const {category='all',search='',sort='recommended',favorites=false,personal=false}=options;const words=search.toLocaleLowerCase('ru-RU').replace(/ё/g,'е').split(/\s+/).filter(Boolean);const list=SHOP_ITEMS.filter(p=>(category==='all'||p.category===category)&&(!favorites||s.productFavorites.includes(p.id))&&(!personal||productAllowed(p,s.profile))&&words.every(w=>(p.name+' '+p.aisle).toLocaleLowerCase('ru-RU').replace(/ё/g,'е').includes(w)));if(sort==='price-up')list.sort((a,b)=>productPrice(a,s.store)-productPrice(b,s.store));if(sort==='price-down')list.sort((a,b)=>productPrice(b,s.store)-productPrice(a,s.store));if(sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'ru'));return list;}
